// Zella - Email Sender: turn one claimed reminder into a "prepare this email" request.
// Only email reminders are handled here. Anything else is skipped with a visible reason, never dropped silently.
const r = $json;
const skip = (reason) => ({ json: { reminder_id: r.reminder_id, finish: { rpc: 'zella_skip_reminder', body: { p_reminder_id: r.reminder_id, p_reason: reason } } } });

const templates = { reminder: 'appointment_reminder', confirmation_request: 'appointment_reminder', confirmation: 'appointment_confirmation' };
const key = templates[r.kind];
if (r.channel !== 'email') return skip('channel_not_email:' + r.channel);
if (!key) return skip('unknown_reminder_kind:' + r.kind);

const tz = (r.business && r.business.timezone) || 'America/New_York';
const start = new Date(r.appointment && r.appointment.start_time);
if (isNaN(start.getTime())) return skip('invalid_appointment_time');
const date = start.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', timeZone: tz });
const time = start.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit', timeZone: tz });
const label = (r.appointment.title || 'appointment').toString().trim().slice(0, 80) || 'appointment';

return {
  json: {
    reminder_id: r.reminder_id,
    business_id: r.business.id,
    customer_id: r.customer.id,
    template_key: key,
    prepare: {
      p_business_id: r.business.id,
      p_customer_id: r.customer.id,
      p_template_key: key,
      p_vars: { appointment: label, date, time },
      p_purpose: 'transactional',
    },
    finish: null,
  },
};

// Zella - Email Sender: read the answer from "prepare" and decide what happens to this reminder.
// Either it goes on to be logged (and maybe sent), or it is finished here: skipped with a reason, or failed.
const plan = $('Plan').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
const finishSkip = (reason) => ({ json: { reminder_id: plan.reminder_id, finish: { rpc: 'zella_skip_reminder', body: { p_reminder_id: plan.reminder_id, p_reason: reason } } } });
const finishFail = (reason) => ({ json: { reminder_id: plan.reminder_id, finish: { rpc: 'zella_complete_reminder', body: { p_reminder_id: plan.reminder_id, p_ok: false, p_error: reason } } } });

if (!(status >= 200 && status < 300)) return finishFail('The database call zella_prepare_email returned ' + status + '.');
if (b.allowed !== true) return finishSkip(String(b.reason || 'not_allowed').slice(0, 60));
if (b.live === true && !b.from) return finishFail('sender_address_not_set');

return {
  json: {
    reminder_id: plan.reminder_id,
    live: b.live === true,
    from: b.from || null,
    from_name: b.from_name || '',
    reply_to: b.reply_to || null,
    to: b.to,
    subject: b.subject,
    text: b.body_text,
    html: b.body_html,
    finish: null,
    log: {
      p_business_id: plan.business_id,
      p_customer_id: plan.customer_id,
      p_to: b.to,
      p_from: b.from || '',
      p_subject: b.subject,
      p_body_text: b.body_text,
      p_body_html: b.body_html,
      p_dedupe_key: 'reminder:' + plan.reminder_id,
      p_status: b.live === true ? 'queued' : 'dry_run',
      p_meta: { reminder_id: plan.reminder_id, template_id: b.template_id, template_version: b.template_version, dry_run: b.live !== true },
    },
  },
};

// Zella - Email Sender: after the email is logged, decide whether to really send.
// A repeat of the same reminder is never sent twice. In dry-run nothing is sent.
const d = $('Decide').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
const done = (rpc, body) => ({ json: { reminder_id: d.reminder_id, finish: { rpc, body } } });

if (!(status >= 200 && status < 300)) {
  return done('zella_complete_reminder', { p_reminder_id: d.reminder_id, p_ok: false, p_error: 'The database call zella_log_outbound_email returned ' + status + '.' });
}
if (b.duplicate === true) {
  if (b.status === 'sent' || b.status === 'delivered') return done('zella_complete_reminder', { p_reminder_id: d.reminder_id, p_ok: true });
  return done('zella_skip_reminder', { p_reminder_id: d.reminder_id, p_reason: 'duplicate_suppressed' });
}
if (d.live !== true) return done('zella_skip_reminder', { p_reminder_id: d.reminder_id, p_reason: 'dry_run: no email was sent' });

const name = String(d.from_name || '').replace(/[\r\n"<>]+/g, ' ').trim();
const resend = { from: name ? name + ' <' + d.from + '>' : d.from, to: [d.to], subject: d.subject, text: d.text, html: d.html };
if (d.reply_to) resend.reply_to = d.reply_to;
return { json: { reminder_id: d.reminder_id, message_id: b.id, finish: null, resend } };

// Zella - Email Sender: turn the provider's answer into the message update and the reminder result.
// The provider's response text is never stored, only its status and a short error name.
const prev = $('After log').item.json;
const status = Number($json.statusCode);
const b = $json.body && typeof $json.body === 'object' ? $json.body : {};
const externalId = b.id ? String(b.id) : null;
const ok = status >= 200 && status < 300 && !!externalId;
const name = typeof b.name === 'string' && /^[a-z_]{1,40}$/.test(b.name) ? ' (' + b.name + ')' : '';
const error = ok ? null : 'The email provider returned ' + status + name + '.';

return {
  json: {
    reminder_id: prev.reminder_id,
    update: { p_id: prev.message_id, p_status: ok ? 'sent' : 'failed', p_external_id: externalId, p_error: error },
    finish: { rpc: 'zella_complete_reminder', body: ok ? { p_reminder_id: prev.reminder_id, p_ok: true } : { p_reminder_id: prev.reminder_id, p_ok: false, p_error: error } },
  },
};
